// Regenerates lib/src/foundations/icons.g.dart from the pinned @carbon/icons
// release. Maintenance-only: the generated file is committed.
//
//   npm pack @carbon/icons@<version> && tar xzf carbon-icons-<version>.tgz
//   node tool/generate_icons.cjs <extracted>/package > lib/src/foundations/icons.g.dart
//
// Icons are converted to path data rather than shipped as SVG assets so they
// paint synchronously, tint through a single color and render identically in
// tests. Add an icon by appending to ICONS; keep doc/carbon-baseline.md current.
const fs = require('fs');
const path = require('path');

const pkg = process.argv[2];
if (!pkg) {
  console.error('usage: node tool/generate_icons.cjs <@carbon/icons package dir>');
  process.exit(2);
}
const version = JSON.parse(fs.readFileSync(path.join(pkg, 'package.json'), 'utf8')).version;

// [dart enum name, carbon file name, mirrors in RTL]
const ICONS = [
  ['add', 'add', false],
  ['arrowLeft', 'arrow--left', true],
  ['arrowRight', 'arrow--right', true],
  ['branch', 'branch', false],
  ['calendar', 'calendar', false],
  ['caretDown', 'caret--down', false],
  ['checkmark', 'checkmark', false],
  ['checkmarkFilled', 'checkmark--filled', false],
  ['checkmarkOutline', 'checkmark--outline', false],
  ['chevronDown', 'chevron--down', false],
  ['chevronLeft', 'chevron--left', true],
  ['chevronRight', 'chevron--right', true],
  ['chevronUp', 'chevron--up', false],
  ['circleDash', 'circle-dash', false],
  ['close', 'close', false],
  ['copy', 'copy', false],
  ['document', 'document', false],
  ['edit', 'edit', false],
  ['error', 'error', false],
  ['errorFilled', 'error--filled', false],
  ['filter', 'filter', false],
  ['idea', 'idea', false],
  ['inProgress', 'in-progress', false],
  ['incomplete', 'incomplete', false],
  ['information', 'information', false],
  ['informationFilled', 'information--filled', false],
  ['launch', 'launch', false],
  ['locked', 'locked', false],
  ['menu', 'menu', false],
  ['misuseOutline', 'misuse--outline', false],
  ['overflowMenuHorizontal', 'overflow-menu--horizontal', false],
  ['overflowMenuVertical', 'overflow-menu--vertical', false],
  ['pendingFilled', 'pending--filled', false],
  ['play', 'play', false],
  ['renew', 'renew', false],
  ['search', 'search', false],
  ['settings', 'settings', false],
  ['star', 'star', false],
  ['subtract', 'subtract', false],
  ['trashCan', 'trash-can', false],
  ['undefinedFilled', 'undefined--filled', false],
  ['unknownFilled', 'unknown--filled', false],
  ['view', 'view', false],
  ['viewOff', 'view--off', false],
  ['warning', 'warning--alt', false],
  ['warningFilled', 'warning--filled', false],
  ['warningAltFilled', 'warning--alt--filled', false],
  ['warningAltInvertedFilled', 'warning--alt-inverted--filled', false],
  ['warningSquareFilled', 'warning-square--filled', false],
];

const attr = (el, name) => {
  const m = el.match(new RegExp(`\\s${name}="([^"]*)"`));
  return m ? m[1] : null;
};
const num = (v) => parseFloat(v);

function toD(el, tag) {
  switch (tag) {
    case 'path':
      return attr(el, 'd').replace(/\s+/g, ' ').trim();
    case 'circle': {
      const cx = num(attr(el, 'cx')), cy = num(attr(el, 'cy')), r = num(attr(el, 'r'));
      return `M${cx - r},${cy}a${r},${r} 0 1,0 ${2 * r},0a${r},${r} 0 1,0 ${-2 * r},0z`;
    }
    case 'rect': {
      const x = num(attr(el, 'x') ?? '0'), y = num(attr(el, 'y') ?? '0');
      const w = num(attr(el, 'width')), h = num(attr(el, 'height'));
      return `M${x},${y}h${w}v${h}h${-w}z`;
    }
    case 'polygon':
      return `M${attr(el, 'points').trim().replace(/\s+/g, ' ')}z`;
    default:
      throw new Error(`unsupported element <${tag}>`);
  }
}

function transformOf(el) {
  const t = attr(el, 'transform');
  if (!t) return null;
  const m = t.match(/^rotate\(\s*(-?[\d.]+)[ ,]+(-?[\d.]+)[ ,]+(-?[\d.]+)\s*\)$/);
  if (!m) throw new Error(`unsupported transform ${t}`);
  return [num(m[1]), num(m[2]), num(m[3])];
}

const dartString = (s) => `'${s.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
const seg = (d, rot) => rot
  ? `_CarbonIconPath(${dartString(d)}, rotation: <double>[${rot.join(', ')}])`
  : `_CarbonIconPath(${dartString(d)})`;

const out = [];
const w = (s = '') => out.push(s);
w(`// GENERATED by tool/generate_icons.cjs from @carbon/icons ${version}. Do not edit.`);
w();
w("part of 'icons.dart';");
w();
w('/// The @carbon/icons release the bundled glyphs were generated from.');
w(`const String carbonIconsVersion = '${version}';`);
w();
w('/// Carbon icons bundled with the package. Glyphs use the 32-unit grid.');
w('enum CarbonIcons {');
for (const [name, file] of ICONS) {
  w(`  /// Carbon \`${file}\`.`);
  w(`  ${name},`);
}
w('  ;');
w();
w('  /// Whether the glyph points along the reading direction and so mirrors');
w('  /// under right-to-left text.');
w('  bool get mirrorsInRtl => _mirrored.contains(this);');
w('}');
w();
w('const Set<CarbonIcons> _mirrored = <CarbonIcons>{');
for (const [name, , mirror] of ICONS) if (mirror) w(`  CarbonIcons.${name},`);
w('};');
w();
w('const Map<CarbonIcons, _CarbonGlyph> _glyphs = <CarbonIcons, _CarbonGlyph>{');
for (const [name, file] of ICONS) {
  const svg = fs.readFileSync(path.join(pkg, 'svg', '32', `${file}.svg`), 'utf8');
  if (!/viewBox="0 0 32 32"/.test(svg)) throw new Error(`${file}: unexpected viewBox`);
  const outer = [], inner = [];
  for (const m of svg.matchAll(/<(path|circle|rect|polygon|ellipse)\b[^>]*\/?>/g)) {
    const [el, tag] = m;
    const isInner = attr(el, 'data-icon-path') === 'inner-path';
    if (!isInner && (attr(el, 'fill') === 'none' || /Transparent_Rectangle/.test(el))) continue;
    (isInner ? inner : outer).push(seg(toD(el, tag), transformOf(el)));
  }
  if (!outer.length) throw new Error(`${file}: no paths`);
  w(`  CarbonIcons.${name}: _CarbonGlyph(`);
  w(`    <_CarbonIconPath>[${outer.join(', ')}],`);
  if (inner.length) w(`    inner: <_CarbonIconPath>[${inner.join(', ')}],`);
  w('  ),');
}
w('};');
process.stdout.write(out.join('\n') + '\n');
